//
// func main() {
//     km, err := NewKeyManager(fetchKeyFromVault())
//     if err != nil {
//         log.Fatal(err)
//     }
//
//     encrypted, err := km.Encrypt([]byte("sensitive data"))
//     if err != nil {
//         log.Fatal(err)
//     }
//
//     decrypted, err := km.Decrypt(encrypted)
//     if err != nil {
//         log.Fatal(err)
//     }
//
//     fmt.Printf("Decrypted: %s\n", decrypted)
// }
```

