### 4. Sample Frontend Code Snippet: Decoding Encrypted Base64 Blob

```typescript
// Example: Decoding base64 encrypted payload received from backend API
function decodeEncryptedPayload(base64Blob: string): Uint8Array {
  // Decode base64 string to bytes
  const binaryString = atob(base64Blob);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

// Usage example
fetch('/api/encrypted-data')
  .then(res => res.json())
  .then(data => {
    const encryptedBytes = decodeEncryptedPayload(data.encryptedPayload);
    // Pass encryptedBytes to backend or store securely if needed
  });
```

