// KeyManager manages AES-256-GCM keys with rotation support.
type KeyManager struct {
    mu          sync.RWMutex
    currentKey  []byte // decoded key bytes
    currentVer  int
    previousKey []byte
    previousVer int
    vaultClient *vault.Client
    secretPath  string
    tracer      trace.Tracer

    // Prometheus metrics
    encryptionLatency prometheus.Histogram
    decryptionLatency prometheus.Histogram
    keyReloads       prometheus.Counter
    vaultCallLatency  prometheus.Histogram
    errorCount       prometheus.Counter
}

// NewKeyManager creates a new KeyManager instance.
func NewKeyManager(vaultClient *vault.Client, secretPath string) (*KeyManager, error) {
    km := &KeyManager{
        vaultClient: vaultClient,
        secretPath:  secretPath,
        tracer:      otel.Tracer("encryption.KeyManager"),
        encryptionLatency: prometheus.NewHistogram(prometheus.HistogramOpts{
            Namespace: "encryption",
            Name:      "encrypt_latency_ms",
            Help:      "Encryption latency in milliseconds",
            Buckets:   prometheus.ExponentialBuckets(1, 2, 10),
        }),
        decryptionLatency: prometheus.NewHistogram(prometheus.HistogramOpts{
            Namespace: "encryption",
            Name:      "decrypt_latency_ms",
            Help:      "Decryption latency in milliseconds",
            Buckets:   prometheus.ExponentialBuckets(1, 2, 10),
        }),
        keyReloads: prometheus.NewCounter(prometheus.CounterOpts{
            Namespace: "encryption",
            Name:      "key_reloads_total",
            Help:      "Total number of key reloads",
        }),
        vaultCallLatency: prometheus.NewHistogram(prometheus.HistogramOpts{
            Namespace: "encryption",
            Name:      "vault_api_call_duration_ms",
            Help:      "Duration of Vault API calls in milliseconds",
            Buckets:   prometheus.ExponentialBuckets(5, 2, 8),
        }),
        errorCount: prometheus.NewCounter(prometheus.CounterOpts{
            Namespace: "encryption",
            Name:      "error_total",
            Help:      "Total number of encryption/decryption errors",
        }),
    }

    // Register metrics (assumes global Prometheus registry)
    prometheus.MustRegister(km.encryptionLatency, km.decryptionLatency, km.keyReloads, km.vaultCallLatency, km.errorCount)

    // Initial key load
    if err := km.loadKeys(context.Background()); err != nil {
        return nil, err
    }

    return km, nil
}

// loadKeys fetches the latest and previous keys from Vault KV v2.
func (km *KeyManager) loadKeys(ctx context.Context) error {
    var lastErr error

    operation := func() error {
        start := time.Now()
        secret, err := km.vaultClient.KVv2("secret").Get(ctx, "encryption/aes256gcm")
        km.vaultCallLatency.Observe(float64(time.Since(start).Milliseconds()))

        if err != nil {
            lastErr = err
            return err
        }

        data, ok := secret.Data["key"].(string)
        if !ok {
            lastErr = errors.New("key not found or invalid type in Vault secret data")
            return lastErr
        }

        keyBytes, err := base64.StdEncoding.DecodeString(data)
        if err != nil {
            lastErr = err
            return err
        }

        if len(keyBytes) != 32 {
            lastErr = errors.New("invalid key length, expected 32 bytes for AES-256")
            return lastErr
        }

        currentVer := secret.Metadata.Version

        // Attempt to load previous version key if exists
        var prevKey []byte
        var prevVer int
        if currentVer > 1 {
            prevSecret, err := km.vaultClient.KVv2("secret").GetVersion(ctx, "encryption/aes256gcm", currentVer-1)
            km.vaultCallLatency.Observe(float64(time.Since(start).Milliseconds()))
            if err == nil {
                prevData, ok := prevSecret.Data["key"].(string)
                if ok {
                    pkb, err := base64.StdEncoding.DecodeString(prevData)
                    if err == nil && len(pkb) == 32 {
                        prevKey = pkb
                        prevVer = prevSecret.Metadata.Version
                    }
                }
            }
        }

        km.mu.Lock()
        defer km.mu.Unlock()

        km.previousKey = km.currentKey
        km.previousVer = km.currentVer

        km.currentKey = keyBytes
        km.currentVer = currentVer

        // If we successfully loaded previous key from Vault, update
        if prevKey != nil && prevVer != km.currentVer {
            km.previousKey = prevKey
            km.previousVer = prevVer
        }

        km.keyReloads.Inc()

        return nil
    }

    // Use exponential backoff retry for Vault calls
    b := backoff.WithContext(backoff.NewExponentialBackOff(), ctx)
    if err := backoff.Retry(operation, b); err != nil {
        return lastErr
    }

    return nil
}

